import{_ as t,o as r,c as e,a2 as o}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"UI 编辑器常见问题","description":"UI 编辑器常见问题：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/faq.md","filePath":"features/ui-editor/faq.md","lastUpdated":1785018026000}'),i={name:"features/ui-editor/faq.md"};function l(n,a,s,d,h,u){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="ui-编辑器常见问题" tabindex="-1">UI 编辑器常见问题 <a class="header-anchor" href="#ui-编辑器常见问题" aria-label="Permalink to &quot;UI 编辑器常见问题&quot;">​</a></h1><h2 id="保存成功但-app-里没变化" tabindex="-1">保存成功但 App 里没变化 <a class="header-anchor" href="#保存成功但-app-里没变化" aria-label="Permalink to &quot;保存成功但 App 里没变化&quot;">​</a></h2><ol><li>列表页该配置是否已 <strong>启用</strong>（绿色状态）</li><li>客户端 <strong>区域</strong> 是否与编辑区域一致</li><li>杀进程重进或下拉刷新；Tab 页有缓存</li><li>是否改错了页面类型（例如改了功能页却看首页）</li></ol><h2 id="侧栏没有-ui管理" tabindex="-1">侧栏没有 UI管理 <a class="header-anchor" href="#侧栏没有-ui管理" aria-label="Permalink to &quot;侧栏没有 UI管理&quot;">​</a></h2><ol><li><strong>系统设置 → 我的模块</strong> 查看 UI 配置是否已开通</li><li><strong>系统设置 → 账号权限</strong> 是否为账号分配 UI 编辑权限</li></ol><h2 id="组件点不了-灰色" tabindex="-1">组件点不了 / 灰色 <a class="header-anchor" href="#组件点不了-灰色" aria-label="Permalink to &quot;组件点不了 / 灰色&quot;">​</a></h2><p>当前 <strong>页面类型</strong> 不允许该组件：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>表单组件灰掉</td><td>不在服务表单页</td></tr><tr><td>轮播、笔记列表灰掉</td><td>在服务表单页（仅允许表单组件）</td></tr><tr><td>笔记列表加不进去</td><td>已有圈子列表或瀑布流（三选一）</td></tr><tr><td>筛选标签加第二个</td><td>每页最多 1 个</td></tr></tbody></table><p>见 <a href="/features/ui-editor/page-types#互斥与唯一性规则">页面类型说明</a>。</p><h2 id="筛选标签切换后列表不刷新" tabindex="-1">筛选标签切换后列表不刷新 <a class="header-anchor" href="#筛选标签切换后列表不刷新" aria-label="Permalink to &quot;筛选标签切换后列表不刷新&quot;">​</a></h2><ol><li>列表 section 与筛选标签的 <strong>联动 Key</strong> 是否一致</li><li>内容模式是否为 <strong>API 联动</strong>（非 Tab 面板模式）</li><li>筛选 Tab 上的排序、分类 ID 是否有效</li></ol><h2 id="点击动作跳转-404" tabindex="-1">点击动作跳转 404 <a class="header-anchor" href="#点击动作跳转-404" aria-label="Permalink to &quot;点击动作跳转 404&quot;">​</a></h2><ol><li>动作中页面路径是否正确</li><li>自定义页是否带 <code>page_type</code> 参数</li><li>目标业务是否已在区域配置中 <strong>启用</strong></li></ol><p>见 <a href="/features/ui-editor/styles-and-actions#点击动作-clickaction">样式与点击动作</a>。</p><h2 id="笔记列表样式改不对位置" tabindex="-1">笔记列表样式改不对位置 <a class="header-anchor" href="#笔记列表样式改不对位置" aria-label="Permalink to &quot;笔记列表样式改不对位置&quot;">​</a></h2><p>笔记/圈子/瀑布流 <strong>样式分层</strong>：</p><ul><li>外壳间距 → <strong>样式 → 外边距</strong></li><li>卡片背景圆角 → <strong>样式 → 内边距/背景</strong>（作用于卡片内）</li><li>标题字号颜色 → <strong>属性</strong> 面板</li></ul><p>见 <a href="/features/ui-editor/styles-and-actions#列表-section-的样式分层">样式与点击动作 — 列表 Section</a>。</p><h2 id="导入-json-后布局乱了" tabindex="-1">导入 JSON 后布局乱了 <a class="header-anchor" href="#导入-json-后布局乱了" aria-label="Permalink to &quot;导入 JSON 后布局乱了&quot;">​</a></h2><ol><li>导入 JSON 来自 <strong>相同页面类型</strong>（home 的 JSON 不要导入到 forum）</li><li>导入会 <strong>完全覆盖</strong> 画布，可先导出当前版本备份</li><li>旧版 JSON 若含已废弃组件类型，编辑器会尝试兼容，个别属性需手动重配</li></ol><h2 id="tabbar-与页面内容对不上" tabindex="-1">TabBar 与页面内容对不上 <a class="header-anchor" href="#tabbar-与页面内容对不上" aria-label="Permalink to &quot;TabBar 与页面内容对不上&quot;">​</a></h2><p>TabBar 与页面配置 <strong>分开保存</strong>：</p><ul><li>改 Tab 文案 → <strong>TabBar配置</strong></li><li>改 Tab 里页面内容 → <strong>页面配置</strong> 对应类型</li></ul><h2 id="服务表单提交按钮不显示" tabindex="-1">服务表单提交按钮不显示 <a class="header-anchor" href="#服务表单提交按钮不显示" aria-label="Permalink to &quot;服务表单提交按钮不显示&quot;">​</a></h2><ol><li>是否添加了 <strong>提交底栏</strong>（每页唯一）</li><li>是否在 <strong>服务表单</strong> 类型页面编辑</li><li>页面是否已 <strong>启用</strong></li></ol><h2 id="小程序广告在-h5-不显示" tabindex="-1">小程序广告在 H5 不显示 <a class="header-anchor" href="#小程序广告在-h5-不显示" aria-label="Permalink to &quot;小程序广告在 H5 不显示&quot;">​</a></h2><p><strong>小程序广告</strong> 仅在微信小程序内展示广告；H5/App 显示 <strong>占位图</strong>，需在属性中配置 <code>fallbackImage</code>。</p><h2 id="多区域维护太累" tabindex="-1">多区域维护太累 <a class="header-anchor" href="#多区域维护太累" aria-label="Permalink to &quot;多区域维护太累&quot;">​</a></h2><p>推荐流程：</p><ol><li><strong>平台默认</strong> 做完整一套 → 启用</li><li>差异区域 <strong>复制</strong> 配置后只改差异部分</li><li>TabBar 同理，先默认再按区域删减 Tab</li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/ui-editor/getting-started">快速上手</a></li><li><a href="/features/ui-editor/page-types">页面类型</a></li><li><a href="/ops/faq">全局 FAQ</a></li></ul>',32)])])}const b=t(i,[["render",l]]);export{c as __pageData,b as default};
